import { expect, expectStatus, test } from "../../fixtures";

test("A certificate expiry date that cannot be parsed gets low confidence", { tag: "@DOC-03" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const vendor = await factory.vendor({ as: "member" });
  const document = await factory.upload(vendor.id, "insurance_certificate", "insurance_certificate_unparseable.txt", "member");

  // Act: wait for background processing to finish.
  await expect
    .poll(
      async () => (await expectStatus<{ status: string }>(await member.get(`/api/documents/${document.id}`), 200)).status,
      { message: "document processing finishes", timeout: 30_000 },
    )
    .toBe("extracted");

  // Assert: re-read the stored extraction, not just the document status.
  const extraction = await expectStatus<{
    fields: Record<string, { value: string | null; confidence: number }>;
  }>(await member.get(`/api/documents/${document.id}/extraction`), 200);
  const expiry = extraction.fields.expiry_date;
  expect(expiry, "expiry_date field is present").toBeDefined();
  expect(expiry.value, "unparseable expiry date is stored as null").toBeNull();
  expect(expiry.confidence, "confidence for an unparseable expiry date").toBeLessThan(0.5);
});
